def recover(self):
    for task in self.tasks(active=True):
        if task["status"] in TERMINAL:
            continue
        if task["provider_task_id"] or task["result_url"]:
            self.update(task["id"], status="recoverable")
        elif task["status"] != "queued":
            self.update(
                task["id"],
                status="interrupted",
                error={
                    "code": "execution_interrupted",
