    """Logical compatibility hosts resolve only to explicitly assembled ASGI components."""

    def __init__(self):
        self.components = {}

    async def handle_async_request(self, request):
        component = self.components.get(request.url.host)
        if component is None and getattr(self, "peer", None) is not None:
            response = await self.peer.external(request)
            if response is not None:
